let proposalRevision=0,proposalBusy=false,proposalSaving=false,proposalRecords=[],proposalCustomers=[],proposalLists=[],proposalPrices=[],proposalOpportunities=[],proposalDraft=[],proposalListId='';
const proposalForm=$('proposal-form'),proposalField=k=>proposalForm.elements.namedItem(k);
