let recurringRevision=0,recurringBusy=false,recurringSaving=false,recurringData=null,recurringFinance=null,recurringSelected=null;
const recurringForms=['renegotiation-form','recurring-rule-form','recurring-generate','recurring-close'].map(id=>$(id)),recField=(f,k)=>f.elements.namedItem(k),recCode=c=>'REC-'+String(c).padStart(8,'0');
function resetRecurring(){recurringRevision++;recurringData=null;recurringFinance=null;recurringSelected=null;for(const f of recurringForms)f.reset();for(const f of recurringForms.slice(2))f.hidden=true;$('recurring-content').hidden=true;for(const id of ['renegotiation-rows','recurring-rules','recurring-occurrences'])$(id).replaceChildren();txt('recurring-status','Aguardando consulta.');txt('renegotiation-info','');}
