function recurringDecimal(n){const s=String(n).padStart(3,'0');return s.slice(0,-2)+'.'+s.slice(-2);}
function renegotiationPreview(){const f=recurringForms[0],balance=recurringBalances().get(recField(f,'obligation_id').value)||0n,n=Number(recField(f,'installment_count').value);const split=financeSplit(recurringDecimal(balance),n);txt('renegotiation-info',split?'Saldo '+proposalCents(balance)+' · '+(n===1?'Parcela única '+proposalCents(split.last):(n-1)+' parcela(s) de '+proposalCents(split.base)+' e última de '+proposalCents(split.last)):'Selecione obrigação com saldo e número válido de parcelas.');f.querySelector('[type=submit]').disabled=!split||recurringSaving;}
