function openRecurringDecision(r,closing){cancelRecurringDecision();recurringSelected=r;const f=recurringForms[closing?3:2];if(closing)txt('recurring-close-title','Encerrar '+recCode(r.code));else{txt('recurring-generate-title','Gerar '+recCode(r.code)+' · período '+(r.generated+1)+' · vencimento '+r.next_due);const d=recField(f,'issued_on');d.max=r.next_due<recurringData.as_of?r.next_due:recurringData.as_of;d.value=d.max;}f.hidden=false;}
