function renderRecurring(){const d=recurringData,history=$('renegotiation-rows'),rules=$('recurring-rules'),occ=$('recurring-occurrences');for(const h of [history,rules,occ])h.replaceChildren();for(const n of d.renegotiations)recRow(history,[financeCode(n.original_code),financeCode(n.replacement_code),commercialMoney(n.principal),n.reason+' · '+n.reference]);if(!d.renegotiations.length)treasuryEmpty(history,4,'Nenhuma renegociação.');for(const r of d.rules){const tr=recRow(rules,[recCode(r.code)+' · '+r.title,financeDirections[r.direction]+' · '+r.company_name+' / '+r.counterparty_name,commercialMoney(r.amount),r.generated+' / '+r.periods,r.next_due,r.status==='closed'?'Encerrada · '+r.close_reason:r.next_due?'Ativa':'Concluída']);const td=node('td');if(r.next_due){for(const [label,closing] of [['Gerar próxima',false],['Encerrar',true]]){const b=node('button',label,'btn light');b.type='button';b.addEventListener('click',()=>openRecurringDecision(r,closing));td.append(b);}}tr.append(td);}if(!d.rules.length)treasuryEmpty(rules,7,'Nenhuma regra registrada.');const map=new Map(d.rules.map(r=>[r.id,r]));for(const x of d.occurrences)recRow(occ,[recCode(map.get(x.rule_id)?.code||''),x.period_no,financeCode(x.obligation_code),x.due_on,commercialMoney(x.amount)]);if(!d.occurrences.length)treasuryEmpty(occ,5,'Nenhuma obrigação gerada.');}
async function refreshRecurring(){if(!authorized||recurringBusy)return;recurringBusy=true;resetRecurring();const rev=recurringRevision;$('recurring-refresh').disabled=true;txt('recurring-status','Consultando registros...');try{const ctx=await registryRequest('/v1/context');if(rev!==recurringRevision||!authorized)return;if(ctx?.finance_recurring!==true)throw Error('Acesso restrito ao proprietário.');const [d,f]=await Promise.all([registryRequest('/v1/finance-recurring'),registryRequest('/v1/financial-obligations')]);if(rev!==recurringRevision||!authorized)return;if(![d?.rules,d?.renegotiations,d?.occurrences,f?.obligations,f?.installments,f?.companies,f?.parties].every(Array.isArray))throw Error('Resposta inválida.');recurringData=d;recurringFinance=f;const [a,b]=recurringForms,balances=recurringBalances();options(recField(a,'obligation_id'),f.obligations.filter(o=>!o.renegotiated&&(balances.get(o.id)||0n)>0n).map(o=>({id:o.id,label:financeCode(o.code)+' · '+o.title+' · '+proposalCents(balances.get(o.id))})),'Selecione obrigação');options(recField(b,'company_id'),f.companies.map(p=>({id:p.id,label:p.name})),'Selecione empresa');options(recField(b,'counterparty_id'),f.parties.map(p=>({id:p.id,label:p.name})),'Selecione contraparte');for(const form of [a,b]){recField(form,'first_due').min=d.as_of;recField(form,'first_due').value=d.as_of;}renegotiationPreview();renderRecurring();$('recurring-content').hidden=false;txt('recurring-status','Registros consultados. Nenhuma geração automática.');}catch(e){if(rev===recurringRevision)txt('recurring-status',e.message);}finally{recurringBusy=false;$('recurring-refresh').disabled=false;}}
