for(const [i,form] of recurringForms.entries())form.addEventListener('submit',async event=>{event.preventDefault();if(!authorized||recurringBusy||recurringSaving||!recurringData||$('recurring-content').hidden||form.hidden)return;const data=Object.fromEntries(new FormData(form));if(i===0){data.expected=recurringDecimal(recurringBalances().get(data.obligation_id)||0n);data.installment_count=Number(data.installment_count);if(!financeSplit(data.expected,data.installment_count))return;}else if(i===1){data.amount=data.amount.trim().replace(',','.');data.periods=Number(data.periods);}else{if(!recurringSelected)return;data.rule_id=recurringSelected.id;if(i===2)data.period_no=recurringSelected.generated+1;}data.request_id=crypto.randomUUID();const rev=recurringRevision,button=form.querySelector('[type=submit]');recurringSaving=true;button.disabled=true;try{const result=await registryRequest('/v1/finance-recurring/'+['renegotiate','rules','generate','close'][i],'POST',data);if(rev!==recurringRevision||!authorized)return;if(!result?.item?.obligation_id&&!result?.item?.rule_id)throw Error('Confirmação não recebida. Consulte antes de repetir.');recurringSaving=false;await refreshRecurring();if(authorized&&!$('recurring-content').hidden)txt('recurring-status','Registro efetuado. Nenhuma cobrança ou operação bancária executada.');}catch(e){if(rev===recurringRevision)txt('recurring-status',e.message+' Consulte antes de repetir.');}finally{recurringSaving=false;button.disabled=false;if(rev===recurringRevision&&i===0)renegotiationPreview();}});

